""C:\\Users\\labops\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command '$ProgressPreference='"'SilentlyContinue'
"'$queries = @(
 @{k='"'te'; q='lnRMSSD smallest worthwhile change typical error reliability athletes'},
 @{k='srpe'; q='session rating of perceived exertion validity training load quantification'},
 @{k='nmfat'; q='neuromuscular fatigue recovery time course 24 48 72 hours jump performance'}
)
foreach ("'$item in $queries) {
  $enc=[uri]::EscapeDataString($item.q)
  $r = Invoke-RestMethod -Uri "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=pubmed&retmax=3&sort=relevance&retmode=json&term=$enc" -TimeoutSec 60
  Write-Output ("### "+$item.k+" : "+(($r.esearchresult.idlist) -join '"','))
  "'$ids=($r.esearchresult.idlist) -join '"','
  if ("'$ids) {
    $s = Invoke-RestMethod -Uri "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi?db=pubmed&retmode=json&id=$ids" -TimeoutSec 60
    foreach ($p in $ids.Split('"',')) {
      "'$d=$s.result.$p
      $doi=($d.articleids | Where-Object {$_.idtype -eq '"'doi'} | Select-Object -First 1).value
      Write-Output (\"PMID {0} | {1} | {2} ({3}) | DOI:{4}\" -f "'$p,$d.title,$d.source,$d.pubdate,$doi)
    }
  }
  Start-Sleep -Milliseconds 400
}'"

